// 1) Validate payload  2) De-duplicate double clicks (same author within 120 s)
const body = $input.first().json.body || {};
const errors = [];
if (!body.author_id) errors.push('author_id missing');
if (!body.log_id) errors.push('log_id missing');
if (!Array.isArray(body.books)) errors.push('books must be an array');

const store = $getWorkflowStaticData('global');
store.recent = store.recent || {};
const now = Date.now();
for (const k of Object.keys(store.recent)) { if (now - store.recent[k] > 120000) delete store.recent[k]; }
const duplicate = !errors.length && !!store.recent[body.author_id];
if (!errors.length && !duplicate) store.recent[body.author_id] = now;

return [{ json: { ...body, _valid: errors.length === 0, _errors: errors.join('; '), _duplicate: duplicate } }];

// Build totals, payout-cycle facts and the AI prompt from the payload Bubble sent.
// ASSUMPTION (check against the Assignment 1 Knowledge Base): royalties are calculated per calendar quarter
// and paid within 45 days after the quarter closes.
const d = $input.first().json;
const inr = n => '\u20b9' + Number(n || 0).toLocaleString('en-IN');
const books = d.books || [];
const published = books.filter(b => (b.status || '').toLowerCase().startsWith('published'));
const inProduction = books.filter(b => !(b.status || '').toLowerCase().startsWith('published'));
const totalEarned = books.reduce((s, b) => s + Number(b.total_royalty_earned || 0), 0);
const totalPaid = books.reduce((s, b) => s + Number(b.royalty_paid || 0), 0);
const totalPending = books.reduce((s, b) => s + Number(b.royalty_pending || 0), 0);

const today = new Date();
const q = Math.floor(today.getUTCMonth() / 3);
const quarterEnd = new Date(Date.UTC(today.getUTCFullYear(), q * 3 + 3, 0));
const payBy = new Date(quarterEnd.getTime() + 45 * 86400000);
const fmt = dt => dt.toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });

const facts = {
  author_name: d.author_name,
  totals: { earned: inr(totalEarned), paid: inr(totalPaid), pending: inr(totalPending) },
  all_paid_up: totalPending === 0,
  current_quarter_ends: fmt(quarterEnd),
  next_payout_expected_by: fmt(payBy),
  published_books: published.map(b => ({ title: b.title, copies_sold: b.total_copies_sold, earned: inr(b.total_royalty_earned), paid: inr(b.royalty_paid), pending: inr(b.royalty_pending), last_payout: b.last_royalty_payout_date || 'no payout yet' })),
  books_in_production: inProduction.map(b => ({ title: b.title, status: b.status }))
};

const system = 'You write royalty summary emails for BookLeaf Publishing, an Indian self-publishing house. Tone: warm, respectful, clear and professional; no hype, no emojis. Use only the facts given; never invent numbers, dates or policies. Amounts are in Indian Rupees exactly as given.';
const user = 'Write a royalty summary email for this author. Requirements:\n1. Greet the author by first name.\n2. For each published book give copies sold, royalty earned, paid and pending.\n3. Give a clear breakdown of total earned, total paid and total pending.\n4. If total pending is above zero, explain that royalties are calculated quarterly and paid within 45 days of the quarter closing, so the next payout is expected by ' + facts.next_payout_expected_by + '.\n5. If everything is paid up, thank them and acknowledge that they are fully up to date.\n6. If any books are in production, add a short status line for each.\n7. Close warmly as \'Team BookLeaf\'.\nReturn ONLY JSON: {"subject": string, "body": string} where body is plain text with line breaks.\n\nFACTS:\n' + JSON.stringify(facts, null, 2);

return [{ json: { log_id: d.log_id, author_id: d.author_id, author_email: d.author_email, facts, system, user } }];

// Parse Gemini's JSON reply; fail loudly if it is not usable.
const ctx = $('Build prompt').first().json;
const res = $input.first().json;
const parts = (((res.candidates || [])[0] || {}).content || {}).parts || [];
const text = parts.map(p => p.text || '').join('').trim();
let parsed;
try { parsed = JSON.parse(text.replace(/^```(json)?/i, '').replace(/```$/, '').trim()); } catch (e) { parsed = null; }
if (!parsed || !parsed.subject || !parsed.body) {
  return [{ json: { ok: false, log_id: ctx.log_id, error: 'AI response was not valid JSON with subject and body' } }];
}
return [{ json: { ok: true, log_id: ctx.log_id, author_email: ctx.author_email, subject: parsed.subject, body: parsed.body } }];
